#!/usr/bin/env bash
# SCRIPT_JDOC: {"summary":"Counterbalance the Q4 N=4 scheduling candidate on the exact historical 512/64 fixture","kind":"mixed","weight":"heavy","role":"entrypoint"}
set -euo pipefail
root=$(cd "$(dirname "$0")/../../.." && pwd);out="$root/benchmarks/intel-1340p/gemma-zc-speed-20260916/q4-schedule-historical";build="$root/build-gemma-zc-speed";runtime="$root/runtime/gemma-vulkan-f32-0bdd7cd8b/runtime";model="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B_q4_0-it.gguf";draft="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B-it-qat-assistant-MTP-Q8_0.gguf";fixture="$root/benchmarks/intel-1340p/gemma-generation-parity-20260916/fixtures/historical-completion-512-64.json";production=llama-gemma-zero-copy.service
mkdir -p "$out/runs";[[ ! -e "$out/complete" ]];export XDG_RUNTIME_DIR=/run/user/$(id -u) DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/$(id -u)/bus
restore(){ local rc=$?;for u in $(systemctl --user list-units --all --plain --no-legend 'gemma-q4-historical-*.service' 2>/dev/null|awk '{print $1}');do systemctl --user stop "$u">/dev/null 2>&1||true;systemctl --user reset-failed "$u">/dev/null 2>&1||true;done;systemctl --user start "$production">/dev/null 2>&1||true;local ok=0;for _ in $(seq 1 180);do if curl -fsS http://127.0.0.1:18094/health>"$out/restored-health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;systemctl --user show "$production" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemorySwapCurrent -p MemorySwapPeak>"$out/restored-service.txt" 2>&1||true;[[ $ok == 1 ]]||rc=1;exit "$rc";};trap restore EXIT INT TERM
systemctl --user is-active --quiet "$production";[[ $(systemctl --user show whisper-stt.service -p ActiveState --value) == inactive ]];[[ $(systemctl --user show whisper-stt-diarizer.service -p ActiveState --value) == inactive ]];! pgrep -x diar-server>/dev/null;! pgrep -x whisper-cli>/dev/null;[[ $(awk '/MemAvailable:/{print $2}' /proc/meminfo) -ge 12582912 ]];systemctl --user stop "$production";printf 'sequence\tarm\tprompt_tps\tgeneration_tps\tprompt_n\tpredicted_n\tdrafted\taccepted\twall_s\tmemory_peak\tswap_peak\tcontent_sha256\n'>"$out/results.tsv"
run_one(){ local seq=$1 arm=$2;local port=$((19900+seq)) unit="gemma-q4-historical-${seq}.service" dir="$out/runs/$(printf '%02d-%s' "$seq" "$arm")";mkdir -p "$dir";local envs=(--setenv=LD_LIBRARY_PATH="$build/bin:$runtime");[[ $arm == on ]]&&envs+=(--setenv=GGML_CPU_EXPERIMENTAL_Q4_N4_SCHEDULE=1 --setenv=GGML_CPU_Q4_N4_SCHEDULE_TRACE=1);systemd-run --user --unit "$unit" --collect -p Type=simple -p TimeoutStopSec=30 -p MemoryMax=16G -p MemorySwapMax=0 -p TasksMax=256 "${envs[@]}" "$build/bin/llama-server" --model "$model" --model-draft "$draft" --alias gemma-q4-historical --load-mode mmap --gpu-layers 0 --threads 8 --threads-batch 16 --ctx-size 32768 --parallel 1 --batch-size 256 --ubatch-size 256 --cache-type-k f16 --cache-type-v f16 --flash-attn off --spec-type draft-mtp --spec-draft-n-min 1 --spec-draft-n-max 3 --spec-draft-threads 8 --spec-draft-threads-batch 16 --spec-draft-type-k f16 --spec-draft-type-v f16 --no-warmup --no-ui --host 127.0.0.1 --port "$port">"$dir/systemd-run.txt";local ok=0;for _ in $(seq 1 180);do if curl -fsS "http://127.0.0.1:$port/health">"$dir/health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;[[ $ok == 1 ]];local start=$(date +%s%N);curl --max-time 120 -fsS "http://127.0.0.1:$port/completion" -H 'Content-Type: application/json' --data-binary @"$fixture">"$dir/response.json";local end=$(date +%s%N);local wall=$(awk -v s="$start" -v e="$end" 'BEGIN{printf "%.9f",(e-s)/1e9}');jq -e '.timings.prompt_n==512 and .timings.predicted_n==64 and .timings.draft_n>0' "$dir/response.json";jq -r .content "$dir/response.json"|sha256sum|cut -d' ' -f1>"$dir/content-sha256.txt";systemctl --user show "$unit" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemoryPeak -p MemorySwapPeak>"$dir/service.txt";local swap=$(sed -n 's/^MemorySwapPeak=//p' "$dir/service.txt");[[ $swap == 0 ]];local mem=$(sed -n 's/^MemoryPeak=//p' "$dir/service.txt");journalctl --user -u "$unit" --no-pager>"$dir/journal.txt";if [[ $arm == on ]];then grep -q Q4_N4_SCHEDULE "$dir/journal.txt";fi;printf '%d\t%s\t%.9f\t%.9f\t%d\t%d\t%d\t%d\t%.9f\t%s\t%s\t%s\n' "$seq" "$arm" "$(jq -r .timings.prompt_per_second "$dir/response.json")" "$(jq -r .timings.predicted_per_second "$dir/response.json")" "$(jq -r .timings.prompt_n "$dir/response.json")" "$(jq -r .timings.predicted_n "$dir/response.json")" "$(jq -r .timings.draft_n "$dir/response.json")" "$(jq -r .timings.draft_n_accepted "$dir/response.json")" "$wall" "$mem" "$swap" "$(cat "$dir/content-sha256.txt")">>"$out/results.tsv";systemctl --user stop "$unit";systemctl --user reset-failed "$unit">/dev/null 2>&1||true;sleep 2;}
run_one 1 off;run_one 2 on;run_one 3 on;run_one 4 off;[[ $(awk -F '\t' 'NR>1{print $5"/"$6"/"$7"/"$8"/"$12}' "$out/results.tsv"|sort -u|wc -l) == 1 ]];awk -F '\t' 'NR>1{s[$2]+=$4;n[$2]++}END{for(a in s)printf "%s_mean_generation_tps=%.9f\n",a,s[a]/n[a]}' "$out/results.tsv"|sort>"$out/summary.txt";sha256sum "$out/results.tsv" "$out/summary.txt">"$out/SHA256SUMS";touch "$out/complete"
